/// <reference types="@stdlib/types"/>

// TypeScript Version: 4.1

import { Layout } from '@stdlib/types/blas';
import { Complex128Array } from '@stdlib/types/array';

/**
* Interface describing `zvander`.
*/
interface Routine {
	/**
	* Generates a double-precision complex floating-point Vandermonde matrix.
	*
	* @param order - storage layout
	* @param mode - mode indicating whether to generate increasing or decreasing powers
	* @param M - number of rows in `out`
	* @param N - number of columns in `out`
	* @param x - input array
	* @param strideX - stride length for `x`
	* @param out - output matrix
	* @param ldo - stride between successive contiguous vectors of the matrix `out` (a.k.a., leading dimension of the matrix `out`)
	* @returns output matrix
	*
	* @example
	* var Complex128Array = require( '@stdlib/array/complex128' );
	*
	* var x = new Complex128Array( [ 1.0, 0.0, 2.0, 0.0 ] );
	* var out = new Complex128Array( 6 );
	*
	* zvander( 'row-major', -1, 2, 3, x, 1, out, 3 );
	* // out => <Complex128Array>[ 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 4.0, 0.0, 2.0, 0.0, 1.0, 0.0 ]
	*/
	( order: Layout, mode: number, M: number, N: number, x: Complex128Array, strideX: number, out: Complex128Array, ldo: number ): Complex128Array;

	/**
	* Generates a double-precision complex floating-point Vandermonde matrix using alternative indexing semantics.
	*
	* @param mode - mode indicating whether to generate increasing or decreasing powers
	* @param M - number of rows in `out`
	* @param N - number of columns in `out`
	* @param x - input array
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @param out - output matrix
	* @param strideOut1 - stride length for the first dimension of `out`
	* @param strideOut2 - stride length for the second dimension of `out`
	* @param offsetOut - starting index for `out`
	* @returns output matrix
	*
	* @example
	* var Complex128Array = require( '@stdlib/array/complex128' );
	*
	* var x = new Complex128Array( [ 1.0, 0.0, 2.0, 0.0 ] );
	* var out = new Complex128Array( 6 );
	*
	* zvander.ndarray( -1, 2, 3, x, 1, 0, out, 3, 1, 0 );
	* // out => <Complex128Array>[ 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 4.0, 0.0, 2.0, 0.0, 1.0, 0.0 ]
	*/
	ndarray( mode: number, M: number, N: number, x: Complex128Array, strideX: number, offsetX: number, out: Complex128Array, strideOut1: number, strideOut2: number, offsetOut: number ): Complex128Array;
}

/**
* Generates a double-precision complex floating-point Vandermonde matrix.
*
* @param order - storage layout
* @param mode - mode indicating whether to generate increasing or decreasing powers
* @param M - number of rows in `out`
* @param N - number of columns in `out`
* @param x - input array
* @param strideX - stride length for `x`
* @param out - output matrix
* @param ldo - stride between successive contiguous vectors of the matrix `out` (a.k.a., leading dimension of the matrix `out`)
* @returns output matrix
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var x = new Complex128Array( [ 1.0, 0.0, 2.0, 0.0 ] );
* var out = new Complex128Array( 6 );
*
* zvander( 'row-major', -1, 2, 3, x, 1, out, 3 );
* // out => <Complex128Array>[ 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 4.0, 0.0, 2.0, 0.0, 1.0, 0.0 ]
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var x = new Complex128Array( [ 1.0, 0.0, 2.0, 0.0 ] );
* var out = new Complex128Array( 6 );
*
* zvander.ndarray( -1, 2, 3, x, 1, 0, out, 3, 1, 0 );
* // out => <Complex128Array>[ 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 4.0, 0.0, 2.0, 0.0, 1.0, 0.0 ]
*/
declare var zvander: Routine;


// EXPORTS //

export = zvander;
